import{_ as i,o as a,c as s,j as e,a as n,a3 as r}from"./chunks/framework.BPaanrMb.js";const v=JSON.parse('{"title":"From Requirements to Pilot Deployment","description":"A five-milestone customer journey from requirements and scenario assessment through solution design, a single-route pilot and scale-up decision.","frontmatter":{"title":"From Requirements to Pilot Deployment","description":"A five-milestone customer journey from requirements and scenario assessment through solution design, a single-route pilot and scale-up decision.","status":"design guidance","content_type":"delivery","keywords":["delivery process","pilot deployment","requirements","site survey","solution design","acceptance metrics"],"scope":"Customer delivery and pilot method for WheelOS short-distance autonomous transport projects","decision_summary":"Validate one route and one cargo type before deciding whether to expand. Every milestone has inputs, deliverables and exit criteria.","best_for":["single-route pilots","fixed-route transport","measurable operating metrics","staged investment"],"not_for":["deployment without a site assessment","operating commitments before chassis confirmation","production claims without evidence"],"next_action":"Complete the scenario fit assessment, then prepare cargo, origins and destinations, frequency, vehicle and current cost data.","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20pilot%20delivery%20plan"},"headers":[],"relativePath":"en/solutions/delivery-process.md","filePath":"en/solutions/delivery-process.md","lastUpdated":1794551845000}'),o={name:"en/solutions/delivery-process.md"};function d(l,t,c,u,h,p){return a(),s("div",null,[...t[0]||(t[0]=[e("h1",{id:"from-requirements-to-pilot-deployment",tabindex:"-1"},[n("From Requirements to Pilot Deployment "),e("a",{class:"header-anchor",href:"#from-requirements-to-pilot-deployment","aria-label":'Permalink to "From Requirements to Pilot Deployment"'},"​")],-1),e("blockquote",null,[e("p",null,"Do not start by building a complete autonomous transport network. Validate one suitable route and its business value, then expand. Build the project like a house: foundation, structure, utilities, inspection and trial operation must all be visible.")],-1),e("div",{class:"delivery-flow",role:"list","aria-label":"Five customer delivery stages"},[e("div",{class:"delivery-flow__node",role:"listitem"},[e("span",null,"01"),e("strong",null,"Requirements")]),e("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),e("div",{class:"delivery-flow__node",role:"listitem"},[e("span",null,"02"),e("strong",null,"Initial assessment")]),e("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),e("div",{class:"delivery-flow__node",role:"listitem"},[e("span",null,"03"),e("strong",null,"Site survey and design")]),e("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),e("div",{class:"delivery-flow__node",role:"listitem"},[e("span",null,"04"),e("strong",null,"Single-route pilot")]),e("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),e("div",{class:"delivery-flow__node",role:"listitem"},[e("span",null,"05"),e("strong",null,"Review and scale")])],-1),r('<h2 id="five-customer-milestones" tabindex="-1">Five customer milestones <a class="header-anchor" href="#five-customer-milestones" aria-label="Permalink to &quot;Five customer milestones&quot;">​</a></h2><h3 id="_1-submit-the-basic-requirements" tabindex="-1">1. Submit the basic requirements <a class="header-anchor" href="#_1-submit-the-basic-requirements" aria-label="Permalink to &quot;1. Submit the basic requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Customer sees</th><th>Customer provides</th><th>WheelOS delivers</th><th>Exit criteria</th></tr></thead><tbody><tr><td>Scenario checklist and meeting notes</td><td>Cargo, origins and destinations, frequency, operating area, current vehicles and staff, special requirements</td><td>Requirement summary, missing-information list and next steps</td><td>The transport task and business objective are clear</td></tr></tbody></table><h3 id="_2-initial-scenario-assessment" tabindex="-1">2. Initial scenario assessment <a class="header-anchor" href="#_2-initial-scenario-assessment" aria-label="Permalink to &quot;2. Initial scenario assessment&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Customer sees</th><th>Customer provides</th><th>WheelOS delivers</th><th>Exit criteria</th></tr></thead><tbody><tr><td>Five-gate assessment, main risks and unknowns</td><td>Actual task data, route conditions, vehicle basis, safety responsibility and current cost</td><td>Fit recommendation, preliminary value judgment and whether a site survey is warranted</td><td>No unresolved hard blocker</td></tr></tbody></table><p>Use the <a href="/en/solutions/fit-assessment">scenario fit assessment tool</a>.</p><h3 id="_3-site-survey-and-solution-design" tabindex="-1">3. Site survey and solution design <a class="header-anchor" href="#_3-site-survey-and-solution-design" aria-label="Permalink to &quot;3. Site survey and solution design&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Customer sees</th><th>Jointly confirmed</th><th>WheelOS delivers</th><th>Exit criteria</th></tr></thead><tbody><tr><td>Site issues, vehicle interfaces, route and risk list</td><td>ODD, stops, loading, owners, acceptance metrics and project scope</td><td>Solution boundary, vehicle and sensor recommendation, integration plan, responsibility matrix and quote inputs</td><td>Safety, regulation, chassis and responsibilities can be assigned</td></tr></tbody></table><h3 id="_4-single-route-pilot-and-validation" tabindex="-1">4. Single-route pilot and validation <a class="header-anchor" href="#_4-single-route-pilot-and-validation" aria-label="Permalink to &quot;4. Single-route pilot and validation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Customer sees</th><th>Pilot scope</th><th>WheelOS delivers</th><th>Exit criteria</th></tr></thead><tbody><tr><td>Daily task dashboard, exception list, metrics and weekly report</td><td>One route or one cargo type</td><td>Integration, calibration, operating logs, issue closure and stage report</td><td>Targets met with controlled risk and traceable issues</td></tr></tbody></table><p>The pilot must record at least:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Baseline</th><th>Pilot result</th></tr></thead><tbody><tr><td>Transport frequency</td><td>Daily tasks, shifts and peak windows</td><td>Actual completed tasks</td></tr><tr><td>Labor input</td><td>Driver, handler, dispatch and intervention hours</td><td>Labor used during the pilot</td></tr><tr><td>Vehicle utilization</td><td>Productive run, waiting and empty-running time</td><td>Effective utilization per vehicle</td></tr><tr><td>On-time rate</td><td>Agreed time window</td><td>Share completed inside the window</td></tr><tr><td>Exceptions</td><td>Interventions, emergency stops, blocked paths and manual recovery</td><td>Exceptions per 100 tasks</td></tr><tr><td>Unit cost</td><td>Cost per task, kilometer or pallet</td><td>Actual pilot unit cost</td></tr><tr><td>Safety events</td><td>Classification rules</td><td>Collisions, near misses, violations and site risks</td></tr></tbody></table><p>These are pilot metrics, not current WheelOS performance data.</p><h3 id="_5-review-optimize-and-decide-whether-to-expand" tabindex="-1">5. Review, optimize and decide whether to expand <a class="header-anchor" href="#_5-review-optimize-and-decide-whether-to-expand" aria-label="Permalink to &quot;5. Review, optimize and decide whether to expand&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Customer sees</th><th>Review content</th><th>Expansion gate</th><th>If expansion is deferred</th></tr></thead><tbody><tr><td>Evidence pack, metric comparison, failure samples and residual risk</td><td>Business value, operating stability, cost, exceptions and safety boundary</td><td>Targets met and conditions exist to add vehicles, routes or tasks</td><td>Retain validated learning, improve the solution or reassess</td></tr></tbody></table><h2 id="seven-engineering-sub-steps" tabindex="-1">Seven engineering sub-steps <a class="header-anchor" href="#seven-engineering-sub-steps" aria-label="Permalink to &quot;Seven engineering sub-steps&quot;">​</a></h2><p>Customers see five milestones; internally they can be decomposed into seven engineering steps:</p><table tabindex="0"><thead><tr><th>Engineering step</th><th>Customer milestone</th><th>Main output</th></tr></thead><tbody><tr><td>Scenario discovery</td><td>1</td><td>Task list and preliminary value case</td></tr><tr><td>Boundary design</td><td>2</td><td>ODD, responsibility matrix and acceptance metrics</td></tr><tr><td>Vehicle and sensors</td><td>3</td><td>Hardware configuration, interface list and installation plan</td></tr><tr><td>Software and data integration</td><td>3–4</td><td>Configuration, calibration, recordings and system checklist</td></tr><tr><td>Replay and controlled-site validation</td><td>4</td><td>Validation report, failures and corrective records</td></tr><tr><td>Pilot operation</td><td>4</td><td>KPIs, issue closure and operating logs</td></tr><tr><td>Assessment and expansion</td><td>5</td><td>Evidence pack, retrospective and expansion recommendation</td></tr></tbody></table><h2 id="do-not-skip-stages" tabindex="-1">Do not skip stages <a class="header-anchor" href="#do-not-skip-stages" aria-label="Permalink to &quot;Do not skip stages&quot;">​</a></h2><ul><li>Do not commit to vehicle integration before chassis and drive-by-wire interfaces are confirmed.</li><li>Do not infer route performance before time sync, frames and calibration are checked.</li><li>Do not make site-validation conclusions without replay and failure samples.</li><li>Do not make business-impact conclusions without a baseline and operating metrics.</li><li>Do not upgrade a pilot to “verified” or a production capability without an evidence record.</li></ul><h2 id="evidence-pack-at-pilot-close" tabindex="-1">Evidence pack at pilot close <a class="header-anchor" href="#evidence-pack-at-pilot-close" aria-label="Permalink to &quot;Evidence pack at pilot close&quot;">​</a></h2><ol><li>Task definition and operating design domain.</li><li>Software, configuration, vehicle and sensor versions.</li><li>Raw logs, recordings and critical replays.</li><li>Baseline, target, actual metrics and statistical method.</li><li>Exceptions, interventions, failure samples and corrective actions.</li><li>Uncovered scenarios, regulatory boundary and residual risk.</li><li>Reviewer and next-stage recommendation.</li></ol><div class="solution-cta"><div><h2>Validate one route before deciding to scale</h2><p>Start with the scenario assessment, then define the task, operating boundary, vehicle conditions and pilot metrics.</p></div><div class="solution-actions"><a class="primary" href="/en/solutions/fit-assessment">Start the fit assessment</a><a href="/en/solutions/applications">Explore six applications</a></div></div>',23)])])}const b=i(o,[["render",d]]);export{v as __pageData,b as default};
